import{_ as p,W as i,s as u,u as l,ah as r,I as n,w as e,Z as s,A as o}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const x=JSON.parse('{"title":"如何在 Ubuntu 命令行下管理浏览器书签 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 命令行下管理浏览器书签 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 命令行下管理浏览器书签 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 命令行下管理浏览器书签 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161027 How to Manage Browser Bookmarks from the Ubuntu Command Line","title":"如何在 Ubuntu 命令行下管理浏览器书签","tag":"201611"},"relativePath":"201611/20161027 How to Manage Browser Bookmarks from the Ubuntu Command Line.md","filePath":"[post].md"}'),d={name:"201611/20161027 How to Manage Browser Bookmarks from the Ubuntu Command Line.md"};function k(b,a,c,h,m,g){const t=i("Link");return l(),u("div",null,[a[13]||(a[13]=r(`<h1 id="如何在-ubuntu-命令行下管理浏览器书签" tabindex="-1">如何在 Ubuntu 命令行下管理浏览器书签 <a class="header-anchor" href="#如何在-ubuntu-命令行下管理浏览器书签" aria-label="Permalink to 如何在 Ubuntu 命令行下管理浏览器书签">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-feature-image.jpg" alt="" title="How to Manage Browser Bookmarks from the Ubuntu Command Lines"></p><p>浏览器书签虽然不常被提及，但是作为互联网浏览的一部分。没有好的书签功能，网站链接可能会丢失，下次再不能访问。这就是为什么一个好的书签管理器很重要。</p><p>所有的现代浏览器都提供了一些形式的管理工具，虽然它们严格上来讲功能较少。如果你已经厌倦了这些内置在浏览器中的主流工具，你或许想要寻找一个替代品。这里介绍 <strong>Buku</strong>：一个命令行下的书签管理器。它不仅可以管理你的书签，还可以给它们加密，将它们保存在一个数据库中等等。下面是如何安装它。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to 安装">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-installing-buku-in-ubuntu.jpg" alt="buku-installing-buku-in-ubuntu" title="buku-installing-buku-in-ubuntu"></p><p>Buku 不是非常流行。因此，用户需要自己编译它。然而，在 Ubuntu 上安装实际上很简单。打开终端并且使用 apt 安装<code>git</code> 和 <code>python3</code>，这两个工具在构建中很关键。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt python3-cryptography python3-bs4</span></span></code></pre></div><p>装完所需的工具后，就可以拉取源码了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/jarun/Buku/.</span></span>
<span class="line"><span>cd Buku</span></span></code></pre></div><p>最后要安装它，只需要运行 <code>make</code> 命令。在这之后就可以在终端中输入 <code>buku</code>来运行 Buku 了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo make install</span></span></code></pre></div><p><strong>注意</strong>：虽然这份指导针对的是 Ubuntu，但是 Buku 可以在任何 Linux 发行版中用相似的方法安装。</p><h3 id="导入书签" tabindex="-1">导入书签 <a class="header-anchor" href="#导入书签" aria-label="Permalink to 导入书签">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-import-bookmarks.jpg" alt="buku-import-bookmarks" title="buku-import-bookmarks"></p><p>要将书签直接导入 Buku 中，首先从浏览器中将书签导出成一个 html 文件。接着，输入下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buku -i bookmarks.html</span></span></code></pre></div><p>最后，导入的书签会添加到 Buku 的数据库中。</p><h3 id="导出书签" tabindex="-1">导出书签 <a class="header-anchor" href="#导出书签" aria-label="Permalink to 导出书签">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-export-bookmarks.jpg" alt="buku-export-bookmarks" title="buku-export-bookmarks"></p><p>导出书签和导入一样简单。要导出所有的书签，使用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buku -e bookmarks.html</span></span></code></pre></div><p>它会和其他书签管理器一样，将数据库中所有的书签导出成一个 html 文件。之后就可以用它做你任何要做的事情了！</p><h3 id="打开书签" tabindex="-1">打开书签 <a class="header-anchor" href="#打开书签" aria-label="Permalink to 打开书签">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-open-bookmarks.jpg" alt="buku-open-bookmarks" title="buku-open-bookmarks"></p><p>要打开一个书签，首先要搜索。这需要用 <code>-s</code> 选项。运行下面的命令来搜索：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buku -s searchterm</span></span></code></pre></div><p>接着一旦找到匹配的结果，输入旁边的数字，书签将会在默认的浏览器中打开了。</p><h3 id="加密" tabindex="-1">加密 <a class="header-anchor" href="#加密" aria-label="Permalink to 加密">​</a></h3><p>不像其他的书签管理器，Buku 可以加密你的数据。这对拥有“敏感”书签的用户而言很有用的功能。要加密数据库，使用 <code>-l</code> 标志来创建一个密码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buku -l</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-encrypt-bookmarks.jpg" alt="buku-encrypt-bookmarks" title="buku-encrypt-bookmarks"></p><p>数据库加锁后，没有输入密码将不能打开书签。要解密它，使用 <code>-k</code> 选项。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buku -k</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-decrypt-bookmarks.jpg" alt="buku-decrypt-bookmarks" title="buku-decrypt-bookmarks"></p><h3 id="其他功能" tabindex="-1">其他功能 <a class="header-anchor" href="#其他功能" aria-label="Permalink to 其他功能">​</a></h3><p>这个书签管理器有许多不同的功能。要了解其他的功能，使用 <code>--help</code> 选项。当使用这个选项后，所有的选项以及每个功能详细内容都会列出来。这个非常有用，由于用户经常忘记东西，并且有时可以打开一个备忘单也不错。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buku --help</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/buku-list-options.jpg" alt="buku-list-options" title="buku-list-options"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>即使这个工具不是浏览器的一部分，它的功能比任何现在管理器提供的功能多。尽管事实是它在命令行中运行，但是也有很好的竞争力。书签对大部分人来言并不重要，但是哪些不喜欢现有选择以及喜欢 Linux 命令行的应该看一下 Buku。</p><hr>`,42)),n("p",null,[a[1]||(a[1]=e("via: ")),s(t,{href:"https://www.maketecheasier.com/manage-browser-bookmarks-ubuntu-command-line/"},{default:o(()=>a[0]||(a[0]=[e("https://www.maketecheasier.com/manage-browser-bookmarks-ubuntu-command-line/")])),_:1})]),n("p",null,[a[5]||(a[5]=e("作者：")),s(t,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:o(()=>a[2]||(a[2]=[e("Derrik Diener")])),_:1}),a[6]||(a[6]=e(" 译者：")),s(t,{href:"https://github.com/geekpi"},{default:o(()=>a[3]||(a[3]=[e("geekpi")])),_:1}),a[7]||(a[7]=e(" 校对：")),s(t,{href:"https://github.com/wxy"},{default:o(()=>a[4]||(a[4]=[e("wxy")])),_:1})]),n("p",null,[a[10]||(a[10]=e("本文由 ")),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>a[8]||(a[8]=[e("LCTT")])),_:1}),a[11]||(a[11]=e(" 原创编译，")),s(t,{href:"https://linux.cn/"},{default:o(()=>a[9]||(a[9]=[e("Linux中国")])),_:1}),a[12]||(a[12]=e(" 荣誉推出"))])])}const C=p(d,[["render",k]]);export{x as __pageData,C as default};
